equation_logic_text:
var calc_output = [];

var immuno = parseFloat(immuno);
var bmi = parseFloat(bmi);
var fracture = parseFloat(fracture);
var esa = parseFloat(esa);
var dox = parseFloat(dox);
var dex = parseFloat(dex);
var race = parseFloat(race);
var hx = parseFloat(hx);
var tunnel = parseFloat(tunnel);
var warfarin = parseFloat(warfarin);
var aspirin = parseFloat(aspirin);

var score = immuno + bmi + fracture + esa + dox + dex + race + hx + tunnel + warfarin + aspirin;

var risk;
if (score <= 3) {
    risk = 'Low';
} else if (score <= 7) {
    risk = 'Intermediate';
} else {
    risk = 'High';
}

calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: risk + ' risk of VTE w/in 6 months'
});
calc_output.push({
    name: '10498_IMPEDE-VTE_result',
    value: score,
    value_text: 'points',
    message: 'IMPEDE-VTE Score'
});
calc_output.push({
    name: '10498_IMPEDE-VTE_interpretation',
    value: risk,
    value_text: 'risk',
    message: 'Risk of VTE within 6 months of treatment initiation'
});
